 269→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
 270→func runEnable(ctx context.Context, w io.Writer) error {
 271→	settings, err := LoadEntireSettings(ctx)
 272→	if err != nil {
 273→		return fmt.Errorf("failed to load settings: %w", err)
 274→	}
 275→
 276→	settings.Enabled = true
 277→	if err := SaveEntireSettings(ctx, settings); err != nil {
 278→		return fmt.Errorf("failed to save settings: %w", err)
 279→	}
 280→
 281→	fmt.Fprintln(w, "Entire is now enabled.")
 282→	return nil
 283→}
