 285→func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
 286→	settings, err := LoadEntireSettings(ctx)
 287→	if err != nil {
 288→		return fmt.Errorf("failed to load settings: %w", err)
 289→	}
 290→
 291→	settings.Enabled = false
 292→
 293→	// If --project flag is specified, always write to project settings
 294→	if useProjectSettings {
 295→		if err := SaveEntireSettings(ctx, settings); err != nil {
 296→			return fmt.Errorf("failed to save settings: %w", err)
 297→		}
 298→	} else {
 299→		// Always write to local settings file (create if doesn't exist)
 300→		if err := SaveEntireSettingsLocal(ctx, settings); err != nil {
 301→			return fmt.Errorf("failed to save local settings: %w", err)
 302→		}
 303→	}
 304→
 305→	fmt.Fprintln(w, "Entire is now disabled.")
 306→	return nil
 307→}
