 309→// DisabledMessage is the message shown when Entire is disabled
 310→const DisabledMessage = "Entire is disabled. Run `entire enable` to re-enable."
 311→
 312→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 313→// Returns true if the caller should exit (i.e., Entire is disabled).
 314→// On error reading settings, defaults to enabled (returns false).
 315→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 316→	enabled, err := IsEnabled(ctx)
 317→	if err != nil {
 318→		// Default to enabled on error
 319→		return false
 320→	}
 321→	if !enabled {
 322→		fmt.Fprintln(w, DisabledMessage)
 323→		return true
 324→	}
 325→	return false
 326→}
