 328→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 329→// installed but are not in the selected list. This handles the case where a user
 330→// re-runs `entire enable` and deselects an agent.
 331→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 332→	installedNames := GetAgentsWithHooksInstalled(ctx)
 333→	if len(installedNames) == 0 {
 334→		return nil
 335→	}
 336→
 337→	selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
 338→	for _, ag := range selectedAgents {
 339→		selectedSet[ag.Name()] = struct{}{}
 340→	}
 341→
 342→	var errs []error
 343→	for _, name := range installedNames {
 344→		if _, selected := selectedSet[name]; selected {
 345→			continue
 346→		}
 347→		ag, err := agent.Get(name)
 348→		if err != nil {
 349→			continue
 350→		}
 351→		hookAgent, ok := agent.AsHookSupport(ag)
 352→		if !ok {
 353→			continue
 354→		}
 355→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 356→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 357→		} else {
 358→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 359→		}
 360→	}
 361→	return errors.Join(errs...)
 362→}
