 364→// setupAgentHooks sets up hooks for a given agent.
 365→// Returns the number of hooks installed (0 if already installed).
 366→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 367→	hookAgent, ok := agent.AsHookSupport(ag)
 368→	if !ok {
 369→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 370→	}
 371→
 372→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 373→	if err != nil {
 374→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 375→	}
 376→
 377→	return count, nil
 378→}
