 380→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 381→// Returns the detected/selected agents and any error.
 382→//
 383→// On first run (no hooks installed):
 384→//   - Single detected agent: used automatically
 385→//   - Multiple/no detected agents: interactive multi-select prompt
 386→//
 387→// On re-run (hooks already installed):
 388→//   - Always shows the interactive multi-select
 389→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 390→//
 391→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 392→// It receives available agent names and returns the selected names.
 393→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 394→	// Check for agents with hooks already installed (re-run detection)
 395→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 396→	hasInstalledHooks := len(installedAgentNames) > 0
 397→
 398→	// Try auto-detection
 399→	detected := agent.DetectAll(ctx)
 400→
 401→	// First run: use existing auto-detect shortcuts
 402→	if !hasInstalledHooks {
 403→		switch {
 404→		case len(detected) == 1:
 405→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 406→			return detected, nil
 407→
 408→		case len(detected) > 1:
 409→			agentTypes := make([]string, 0, len(detected))
 410→			for _, ag := range detected {
 411→				agentTypes = append(agentTypes, string(ag.Type()))
 412→			}
 413→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 414→			fmt.Fprintln(w)
 415→		}
 416→	}
 417→
 418→	// Check if we can prompt interactively
 419→	if !canPromptInteractively() {
 420→		if hasInstalledHooks {
 421→			// Re-run without TTY — keep currently installed agents
 422→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 423→			for _, name := range installedAgentNames {
 424→				ag, err := agent.Get(name)
 425→				if err != nil {
 426→					continue
 427→				}
 428→				agents = append(agents, ag)
 429→			}
 430→			return agents, nil
 431→		}
 432→		if len(detected) > 0 {
 433→			return detected, nil
 434→		}
 435→		defaultAgent := agent.Default()
 436→		if defaultAgent == nil {
 437→			return nil, errors.New("no default agent available")
 438→		}
 439→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 440→		return []agent.Agent{defaultAgent}, nil
 441→	}
 442→
 443→	if !hasInstalledHooks && len(detected) == 0 {
 444→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 445→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 446→		fmt.Fprintln(w)
 447→	}
 448→
 449→	// Build pre-selection set.
 450→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 451→	// On first run: pre-select all detected agents.
 452→	preSelectedSet := make(map[types.AgentName]struct{})
 453→	if hasInstalledHooks {
 454→		for _, name := range installedAgentNames {
 455→			preSelectedSet[name] = struct{}{}
 456→		}
 457→	} else {
 458→		for _, ag := range detected {
 459→			preSelectedSet[ag.Name()] = struct{}{}
 460→		}
 461→	}
 462→
 463→	// Build options from registered agents
 464→	agentNames := agent.List()
 465→	options := make([]huh.Option[string], 0, len(agentNames))
 466→	for _, name := range agentNames {
 467→		ag, err := agent.Get(name)
 468→		if err != nil {
 469→			continue
 470→		}
 471→		// Only show agents that support hooks
 472→		if _, ok := agent.AsHookSupport(ag); !ok {
 473→			continue
 474→		}
 475→		// Skip test-only agents (e.g., Vogon canary)
 476→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
 477→			continue
 478→		}
 479→		opt := huh.NewOption(string(ag.Type()), string(name))
 480→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 481→			opt = opt.Selected(true)
 482→		}
 483→		options = append(options, opt)
 484→	}
 485→
 486→	if len(options) == 0 {
 487→		return nil, errors.New("no agents with hook support available")
 488→	}
 489→
 490→	// Collect available agent names for the selector
 491→	availableNames := make([]string, 0, len(options))
 492→	for _, opt := range options {
 493→		availableNames = append(availableNames, opt.Value)
 494→	}
 495→
 496→	var selectedAgentNames []string
 497→	if selectFn != nil {
 498→		var err error
 499→		selectedAgentNames, err = selectFn(availableNames)
 500→		if err != nil {
 501→			return nil, err
 502→		}
 503→		if len(selectedAgentNames) == 0 {
 504→			return nil, errors.New("no agents selected")
 505→		}
 506→	} else {
 507→		form := NewAccessibleForm(
 508→			huh.NewGroup(
 509→				huh.NewMultiSelect[string]().
 510→					Title("Which agents are you using?").
 511→					Description("Use space to select, enter to confirm.").
 512→					Options(options...).
 513→					Validate(func(selected []string) error {
 514→						if len(selected) == 0 {
 515→							return errors.New("please select at least one agent")
 516→						}
 517→						return nil
 518→					}).
 519→					Value(&selectedAgentNames),
 520→			),
 521→		)
 522→		if err := form.Run(); err != nil {
 523→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 524→		}
 525→	}
 526→
 527→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 528→	for _, name := range selectedAgentNames {
 529→		selectedAgent, err := agent.Get(types.AgentName(name))
 530→		if err != nil {
 531→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 532→		}
 533→		selectedAgents = append(selectedAgents, selectedAgent)
 534→	}
 535→
 536→	agentTypes := make([]string, 0, len(selectedAgents))
 537→	for _, ag := range selectedAgents {
 538→		agentTypes = append(agentTypes, string(ag.Type()))
 539→	}
 540→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 541→	return selectedAgents, nil
 542→}
