 544→// canPromptInteractively checks if we can show interactive prompts.
 545→// Returns false when running in CI, tests, or other non-interactive environments.
 546→func canPromptInteractively() bool {
 547→	// Check for test environment
 548→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 549→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 550→	}
 551→
 552→	// Check if /dev/tty is available
 553→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 554→	if err != nil {
 555→		return false
 556→	}
 557→	_ = tty.Close()
 558→	return true
 559→}
