 561→// printAgentError writes an error message followed by available agents and usage.
 562→func printAgentError(w io.Writer, message string) {
 563→	agents := agent.List()
 564→	fmt.Fprintf(w, "%s Available agents:\n", message)
 565→	fmt.Fprintln(w)
 566→	for _, a := range agents {
 567→		suffix := ""
 568→		if a == agent.DefaultAgentName {
 569→			suffix = "    (default)"
 570→		}
 571→		fmt.Fprintf(w, "  %s%s\n", a, suffix)
 572→	}
 573→	fmt.Fprintln(w)
 574→	fmt.Fprintln(w, "Usage: entire enable --agent <agent-name>")
 575→}
