 683→// determineSettingsTarget decides whether to write to settings.local.json based on:
 684→// - Whether settings.json already exists
 685→// - The --local and --project flags
 686→// Returns (useLocal, showNotification).
 687→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 688→	// Explicit --local flag always uses local settings
 689→	if useLocal {
 690→		return true, false
 691→	}
 692→
 693→	// Explicit --project flag always uses project settings
 694→	if useProject {
 695→		return false, false
 696→	}
 697→
 698→	// No flags specified - check if settings file exists
 699→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
 700→	if _, err := os.Stat(settingsPath); err == nil {
 701→		// Settings file exists - auto-redirect to local with notification
 702→		return true, true
 703→	}
 704→
 705→	// Settings file doesn't exist - create it
 706→	return false, false
 707→}
