 779→// shellCompletionComment is the comment preceding the completion line
 780→const shellCompletionComment = "# Entire CLI shell completion"
 781→
 782→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 783→var errUnsupportedShell = errors.New("unsupported shell")
 784→
 785→// shellCompletionTarget returns the rc file path and completion lines for the
 786→// user's current shell.
 787→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 788→	home, err := os.UserHomeDir()
 789→	if err != nil {
 790→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 791→	}
 792→
 793→	shell := os.Getenv("SHELL")
 794→	switch {
 795→	case strings.Contains(shell, "zsh"):
 796→		return "Zsh",
 797→			filepath.Join(home, ".zshrc"),
 798→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 799→			nil
 800→	case strings.Contains(shell, "bash"):
 801→		bashRC := filepath.Join(home, ".bashrc")
 802→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 803→			bashRC = filepath.Join(home, ".bash_profile")
 804→		}
 805→		return "Bash",
 806→			bashRC,
 807→			"source <(entire completion bash)",
 808→			nil
 809→	case strings.Contains(shell, "fish"):
 810→		return "Fish",
 811→			filepath.Join(home, ".config", "fish", "config.fish"),
 812→			"entire completion fish | source",
 813→			nil
 814→	default:
 815→		return "", "", "", errUnsupportedShell
 816→	}
 817→}
 818→
 819→// promptShellCompletion offers to add shell completion to the user's rc file.
 820→// Only prompts if completion is not already configured.
 821→func promptShellCompletion(w io.Writer) error {
 822→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 823→	if err != nil {
 824→		if errors.Is(err, errUnsupportedShell) {
 825→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 826→			return nil
 827→		}
 828→		return fmt.Errorf("shell completion: %w", err)
 829→	}
 830→
 831→	if isCompletionConfigured(rcFile) {
 832→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 833→		return nil
 834→	}
 835→
 836→	var selected string
 837→	form := NewAccessibleForm(
 838→		huh.NewGroup(
 839→			huh.NewSelect[string]().
 840→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 841→				Options(
 842→					huh.NewOption("Yes", "yes"),
 843→					huh.NewOption("No", "no"),
 844→				).
 845→				Value(&selected),
 846→		),
 847→	)
 848→
 849→	if err := form.Run(); err != nil {
 850→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 851→		return nil
 852→	}
 853→
 854→	if selected != "yes" {
 855→		return nil
 856→	}
 857→
 858→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 859→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 860→	}
 861→
 862→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 863→	fmt.Fprintln(w, "  Restart your shell to activate")
 864→
 865→	return nil
 866→}
 867→
 868→// isCompletionConfigured checks if shell completion is already in the rc file.
 869→func isCompletionConfigured(rcFile string) bool {
 870→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 871→	content, err := os.ReadFile(rcFile)
 872→	if err != nil {
 873→		return false // File doesn't exist or can't read, treat as not configured
 874→	}
 875→	return strings.Contains(string(content), "entire completion")
 876→}
 877→
 878→// appendShellCompletion adds the completion line to the rc file.
 879→func appendShellCompletion(rcFile, completionLine string) error {
 880→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 881→		return fmt.Errorf("creating directory: %w", err)
 882→	}
 883→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 884→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 885→	if err != nil {
 886→		return fmt.Errorf("opening file: %w", err)
 887→	}
 888→	defer f.Close()
 889→
 890→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 891→	if err != nil {
 892→		return fmt.Errorf("writing completion: %w", err)
 893→	}
 894→	return nil
 895→}
