 940→// runUninstall completely removes Entire from the repository.
 941→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 942→	// Check if we're in a git repository
 943→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 944→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 945→		return NewSilentError(errors.New("not a git repository"))
 946→	}
 947→
 948→	// Gather counts for display
 949→	sessionStateCount := countSessionStates(ctx)
 950→	shadowBranchCount := countShadowBranches(ctx)
 951→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 952→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 953→	entireDirExists := checkEntireDirExists(ctx)
 954→
 955→	// Check if there's anything to uninstall
 956→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 957→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 958→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 959→		return nil
 960→	}
 961→
 962→	// Show confirmation prompt unless --force
 963→	if !force {
 964→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 965→		if entireDirExists {
 966→			fmt.Fprintln(w, "  - .entire/ directory")
 967→		}
 968→		if gitHooksInstalled {
 969→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 970→		}
 971→		if sessionStateCount > 0 {
 972→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 973→		}
 974→		if shadowBranchCount > 0 {
 975→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 976→		}
 977→		if len(agentsWithInstalledHooks) > 0 {
 978→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 979→			for _, name := range agentsWithInstalledHooks {
 980→				if ag, err := agent.Get(name); err == nil {
 981→					displayNames = append(displayNames, string(ag.Type()))
 982→				}
 983→			}
 984→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 985→		}
 986→		fmt.Fprintln(w)
 987→
 988→		var confirmed bool
 989→		form := NewAccessibleForm(
 990→			huh.NewGroup(
 991→				huh.NewConfirm().
 992→					Title("Are you sure you want to uninstall Entire?").
 993→					Affirmative("Yes, uninstall").
 994→					Negative("Cancel").
 995→					Value(&confirmed),
 996→			),
 997→		)
 998→
 999→		if err := form.Run(); err != nil {
1000→			return fmt.Errorf("confirmation cancelled: %w", err)
1001→		}
1002→
1003→		if !confirmed {
1004→			fmt.Fprintln(w, "Uninstall cancelled.")
1005→			return nil
1006→		}
1007→	}
1008→
1009→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1010→
1011→	// 1. Remove agent hooks (lowest risk)
1012→	if err := removeAgentHooks(ctx, w); err != nil {
1013→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1014→	}
1015→
1016→	// 2. Remove git hooks
1017→	removed, err := strategy.RemoveGitHook(ctx)
1018→	if err != nil {
1019→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1020→	} else if removed > 0 {
1021→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1022→	}
1023→
1024→	// 3. Remove session state files
1025→	statesRemoved, err := removeAllSessionStates(ctx)
1026→	if err != nil {
1027→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1028→	} else if statesRemoved > 0 {
1029→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1030→	}
1031→
1032→	// 4. Remove .entire/ directory
1033→	if err := removeEntireDirectory(ctx); err != nil {
1034→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1035→	} else if entireDirExists {
1036→		fmt.Fprintln(w, "  Removed .entire directory")
1037→	}
1038→
1039→	// 5. Remove shadow branches
1040→	branchesRemoved, err := removeAllShadowBranches(ctx)
1041→	if err != nil {
1042→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1043→	} else if branchesRemoved > 0 {
1044→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1045→	}
1046→
1047→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1048→	return nil
1049→}
