1083→// removeAgentHooks removes hooks from all agents that support hooks.
1084→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1085→	var errs []error
1086→	for _, name := range agent.List() {
1087→		ag, err := agent.Get(name)
1088→		if err != nil {
1089→			continue
1090→		}
1091→		hs, ok := agent.AsHookSupport(ag)
1092→		if !ok {
1093→			continue
1094→		}
1095→		wasInstalled := hs.AreHooksInstalled(ctx)
1096→		if err := hs.UninstallHooks(ctx); err != nil {
1097→			errs = append(errs, err)
1098→		} else if wasInstalled {
1099→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1100→		}
1101→	}
1102→	return errors.Join(errs...)
1103→}
