1105→// removeAllSessionStates removes all session state files and the directory.
1106→func removeAllSessionStates(ctx context.Context) (int, error) {
1107→	store, err := session.NewStateStore(ctx)
1108→	if err != nil {
1109→		return 0, fmt.Errorf("failed to create state store: %w", err)
1110→	}
1111→
1112→	// Count states before removing
1113→	states, err := store.List(ctx)
1114→	if err != nil {
1115→		return 0, fmt.Errorf("failed to list session states: %w", err)
1116→	}
1117→	count := len(states)
1118→
1119→	// Remove the entire directory
1120→	if err := store.RemoveAll(); err != nil {
1121→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1122→	}
1123→
1124→	return count, nil
1125→}
