1127→// removeEntireDirectory removes the .entire directory.
1128→func removeEntireDirectory(ctx context.Context) error {
1129→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1130→	if err != nil {
1131→		entireDirAbs = paths.EntireDir
1132→	}
1133→	if err := os.RemoveAll(entireDirAbs); err != nil {
1134→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1135→	}
1136→	return nil
