1139→// removeAllShadowBranches removes all shadow branches.
1140→func removeAllShadowBranches(ctx context.Context) (int, error) {
1141→	branches, err := strategy.ListShadowBranches(ctx)
1142→	if err != nil {
1143→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1144→	}
1145→	if len(branches) == 0 {
1146→		return 0, nil
1147→	}
1148→	deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
1149→	return len(deleted), err
